import { defineConfig } from 'vite';
import react from '@vitejs/plugin-react';

export default defineConfig({
  base: './',
  plugins: [react()],
  build: { outDir: 'dist', emptyOutDir: true },
});

// Shapes the screens work with. Every provider (UAZAPI today, others later)
// turns its own data into these, so the screens never depend on one provider.

export interface Connection {
  id: string;
  provider: 'uazapi';
  name: string;
  url: string; // server base URL, no trailing slash
  token: string; // instance token
}

export interface Chat {
  id: string; // stable key (wa_fastid / owner:number)
  rowId: string; // provider row id used by editLead
  chatId: string; // full chat id, e.g. 5511...@s.whatsapp.net
  number: string; // what /send/* expects
  name: string;
  phone: string;
  image: string;
  isGroup: boolean;
  unread: number;
  lastAt: number; // ms
  lastText: string;
  lastType: string;
  lastFromMe: boolean;
  archived: boolean;
  pinned: boolean;
  blocked: boolean;
  mutedUntil: number;
  labels: string[];
  lead: Lead;
  presence?: string;
  raw: Record<string, unknown>;
}

export interface Lead {
  name: string;
  fullName: string;
  email: string;
  personalId: string;
  status: string;
  notes: string;
  tags: string[];
  ticketOpen: boolean;
  assignedTo: string;
  botPausedUntil: number; // ms; 0 = robot free to answer
}

export type MessageKind =
  | 'text'
  | 'image'
  | 'video'
  | 'audio'
  | 'document'
  | 'sticker'
  | 'location'
  | 'contact'
  | 'reaction'
  | 'poll'
  | 'deleted'
  | 'other';

export interface Message {
  id: string;
  chatId: string;
  fromMe: boolean;
  at: number;
  kind: MessageKind;
  type: string;
  text: string;
  caption: string;
  senderName: string;
  status: string;
  quotedId: string;
  reaction: string;
  edited: string;
  fileUrl: string;
  thumb: string; // data: url
  fileName: string;
  mime: string;
  seconds: number;
  lat?: number;
  lng?: number;
  pending?: boolean;
  failed?: boolean;
  raw: Record<string, unknown>;
}

export interface Label {
  id: string;
  name: string;
  color: string;
}

export interface QuickReply {
  id: string;
  shortCut: string;
  text: string;
}

export type ChatFilter =
  | 'all'
  | 'unread'
  | 'groups'
  | 'mine'
  | 'open'
  | 'archived'
  | 'blocked';

export type LiveEvent =
  | { kind: 'chat'; chat: Chat }
  | { kind: 'message'; message: Message }
  | { kind: 'status'; ids: string[]; status: string }
  | { kind: 'presence'; chatKey: string; number: string; state: string }
  | { kind: 'connection'; state: 'connecting' | 'live' | 'down' };

import type { Connection } from '../provider/types';

const KEY = 'multi.connections.v1';
const ACTIVE = 'multi.active.v1';
const SETTINGS = 'multi.settings.v1';

export interface Settings {
  attendantId: string; // what goes in lead_assignedAttendant_id
  attendantName: string;
  signMessages: boolean;
  sound: boolean;
  botPauseHours: number;
}

export const defaultSettings: Settings = {
  attendantId: '',
  attendantName: '',
  signMessages: false,
  sound: true,
  botPauseHours: 24,
};

function read<T>(key: string, fallback: T): T {
  try {
    const v = localStorage.getItem(key);
    return v ? (JSON.parse(v) as T) : fallback;
  } catch {
    return fallback;
  }
}

export function loadConnections(): Connection[] {
  return read<Connection[]>(KEY, []);
}

export function saveConnections(list: Connection[]) {
  localStorage.setItem(KEY, JSON.stringify(list));
}

export function loadActiveId(): string {
  return localStorage.getItem(ACTIVE) || '';
}

export function saveActiveId(id: string) {
  if (id) localStorage.setItem(ACTIVE, id);
  else localStorage.removeItem(ACTIVE);
}

export function loadSettings(): Settings {
  return { ...defaultSettings, ...read<Partial<Settings>>(SETTINGS, {}) };
}

export function saveSettings(s: Settings) {
  localStorage.setItem(SETTINGS, JSON.stringify(s));
}

import type { ReactNode } from 'react';

const pad = (n: number) => String(n).padStart(2, '0');

export function timeOf(ms: number) {
  if (!ms) return '';
  const d = new Date(ms);
  return `${pad(d.getHours())}:${pad(d.getMinutes())}`;
}

function sameDay(a: Date, b: Date) {
  return a.getFullYear() === b.getFullYear() && a.getMonth() === b.getMonth() && a.getDate() === b.getDate();
}

/** Chat list stamp: hour today, "Ontem", weekday this week, else dd/mm/yyyy. */
export function listStamp(ms: number) {
  if (!ms) return '';
  const d = new Date(ms);
  const now = new Date();
  if (sameDay(d, now)) return timeOf(ms);
  const y = new Date(now);
  y.setDate(now.getDate() - 1);
  if (sameDay(d, y)) return 'Ontem';
  const diff = (now.getTime() - ms) / 86400000;
  if (diff < 7) return d.toLocaleDateString('pt-BR', { weekday: 'long' });
  return `${pad(d.getDate())}/${pad(d.getMonth() + 1)}/${d.getFullYear()}`;
}

export function dayLabel(ms: number) {
  const d = new Date(ms);
  const now = new Date();
  if (sameDay(d, now)) return 'Hoje';
  const y = new Date(now);
  y.setDate(now.getDate() - 1);
  if (sameDay(d, y)) return 'Ontem';
  return `${pad(d.getDate())}/${pad(d.getMonth() + 1)}/${d.getFullYear()}`;
}

export function duration(sec: number) {
  if (!sec) return '';
  return `${Math.floor(sec / 60)}:${pad(Math.floor(sec % 60))}`;
}

export function formatPhone(n: string) {
  const d = n.replace(/\D/g, '');
  if (d.length === 13 && d.startsWith('55')) return `+55 ${d.slice(2, 4)} ${d.slice(4, 9)}-${d.slice(9)}`;
  if (d.length === 12 && d.startsWith('55')) return `+55 ${d.slice(2, 4)} ${d.slice(4, 8)}-${d.slice(8)}`;
  return d ? `+${d}` : n;
}

export function initials(name: string) {
  const parts = name.trim().split(/\s+/).filter(Boolean);
  if (!parts.length) return '';
  return (parts[0][0] + (parts.length > 1 ? parts[parts.length - 1][0] : '')).toUpperCase();
}

/** WhatsApp text formatting: *bold* _italic_ ~strike~ ```mono``` and links. */
export function richText(text: string): ReactNode[] {
  const out: ReactNode[] = [];
  const re = /(```[\s\S]+?```|\*[^*\n]+\*|_[^_\n]+_|~[^~\n]+~|https?:\/\/[^\s]+)/g;
  let last = 0;
  let m: RegExpExecArray | null;
  let k = 0;
  while ((m = re.exec(text))) {
    if (m.index > last) out.push(text.slice(last, m.index));
    const t = m[0];
    if (t.startsWith('```')) out.push(<code key={k++}>{t.slice(3, -3)}</code>);
    else if (t.startsWith('*')) out.push(<strong key={k++}>{t.slice(1, -1)}</strong>);
    else if (t.startsWith('_')) out.push(<em key={k++}>{t.slice(1, -1)}</em>);
    else if (t.startsWith('~')) out.push(<s key={k++}>{t.slice(1, -1)}</s>);
    else
      out.push(
        <a key={k++} href={t} target="_blank" rel="noreferrer">
          {t}
        </a>,
      );
    last = m.index + t.length;
  }
  if (last < text.length) out.push(text.slice(last));
  return out;
}

export function fileToDataUrl(file: Blob): Promise<string> {
  return new Promise((resolve, reject) => {
    const r = new FileReader();
    r.onload = () => resolve(String(r.result));
    r.onerror = () => reject(r.error);
    r.readAsDataURL(file);
  });
}

export function mediaTypeFor(mime: string) {
  if (mime.startsWith('image/')) return mime === 'image/webp' ? 'sticker' : 'image';
  if (mime.startsWith('video/')) return 'video';
  if (mime.startsWith('audio/')) return 'audio';
  return 'document';
}

// Voice notes: record with the microphone, then turn the recording into MP3
// before sending (WhatsApp providers such as UAZAPI take MP3 or Ogg/Opus, not
// the WebM browsers record). The Bubble app did the same with an MP3 recorder.
import { Mp3Encoder } from '@breezystack/lamejs';

export class VoiceRecorder {
  private rec: MediaRecorder | null = null;
  private chunks: Blob[] = [];
  private stream: MediaStream | null = null;
  startedAt = 0;

  async start() {
    this.stream = await navigator.mediaDevices.getUserMedia({ audio: true });
    this.chunks = [];
    this.rec = new MediaRecorder(this.stream);
    this.rec.ondataavailable = (e) => e.data.size && this.chunks.push(e.data);
    this.rec.start();
    this.startedAt = Date.now();
  }

  private finish(): Promise<Blob> {
    return new Promise((resolve) => {
      const rec = this.rec;
      if (!rec) return resolve(new Blob());
      rec.onstop = () => {
        this.stream?.getTracks().forEach((t) => t.stop());
        resolve(new Blob(this.chunks, { type: rec.mimeType }));
      };
      rec.stop();
    });
  }

  cancel() {
    this.finish();
    this.rec = null;
  }

  /** Stops and returns an MP3 data URL. */
  async stop(): Promise<{ dataUrl: string; seconds: number }> {
    const blob = await this.finish();
    this.rec = null;
    const buf = await blob.arrayBuffer();
    const ctx = new AudioContext();
    const audio = await ctx.decodeAudioData(buf);
    ctx.close();
    const mp3 = encodeMp3(audio);
    const dataUrl = await new Promise<string>((resolve) => {
      const r = new FileReader();
      r.onload = () => resolve(String(r.result));
      r.readAsDataURL(mp3);
    });
    return { dataUrl, seconds: Math.round(audio.duration) };
  }
}

function encodeMp3(audio: AudioBuffer): Blob {
  const rate = audio.sampleRate;
  const data = audio.getChannelData(0);
  const samples = new Int16Array(data.length);
  for (let i = 0; i < data.length; i++) {
    const s = Math.max(-1, Math.min(1, data[i]));
    samples[i] = s < 0 ? s * 0x8000 : s * 0x7fff;
  }
  const enc = new Mp3Encoder(1, rate, 64);
  const parts: BlobPart[] = [];
  const block = 1152;
  for (let i = 0; i < samples.length; i += block) {
    const out = enc.encodeBuffer(samples.subarray(i, i + block));
    if (out.length) parts.push(new Uint8Array(out));
  }
  const end = enc.flush();
  if (end.length) parts.push(new Uint8Array(end));
  return new Blob(parts, { type: 'audio/mpeg' });
}

import { useState } from 'react';
import { Icon } from './Icon';

export function Avatar({ src, group, size = 44 }: { src?: string; group?: boolean; size?: number }) {
  const [broken, setBroken] = useState(false);
  const style = { width: size, height: size, minWidth: size };
  if (src && !broken)
    return <img className="avatar" style={style} src={src} alt="" onError={() => setBroken(true)} />;
  return (
    <span className="avatar ph" style={style}>
      <Icon name={group ? 'group' : 'person'} size={Math.round(size * 0.62)} />
    </span>
  );
}

import { useEffect, useRef } from 'react';
import { Icon } from './Icon';

export interface MenuItem {
  label: string;
  icon?: string;
  checked?: boolean;
  danger?: boolean;
  disabled?: boolean;
  onClick: () => void;
}

export function Menu({ items, onClose, align = 'right' }: { items: MenuItem[]; onClose: () => void; align?: 'left' | 'right' }) {
  const ref = useRef<HTMLDivElement>(null);
  useEffect(() => {
    const down = (e: MouseEvent) => {
      if (ref.current && !ref.current.contains(e.target as Node)) onClose();
    };
    const key = (e: KeyboardEvent) => e.key === 'Escape' && onClose();
    setTimeout(() => document.addEventListener('mousedown', down), 0);
    document.addEventListener('keydown', key);
    return () => {
      document.removeEventListener('mousedown', down);
      document.removeEventListener('keydown', key);
    };
  }, [onClose]);
  return (
    <div className={'menu ' + align} ref={ref} role="menu">
      {items.map((it, i) => (
        <button
          key={i}
          role="menuitem"
          className={'menu-item' + (it.danger ? ' danger' : '') + (it.checked ? ' checked' : '')}
          disabled={it.disabled}
          onClick={() => {
            onClose();
            it.onClick();
          }}
        >
          {it.icon && <Icon name={it.icon} size={18} />}
          <span>{it.label}</span>
          {it.checked && <Icon name="check" size={18} className="menu-check" />}
        </button>
      ))}
    </div>
  );
}

